# The swscale version whose threaded RGBA -> YUV conversion was checked to give
# the same bytes as its single-threaded one for every even frame size tried
# (480 conversions: 2x2 up to 14336x8064, yuv420p and nv12, 2-8 threads). An
# older one (FFmpeg 8.0.1's 9.1) differed at 854x480, so it keeps PyAV's path.
_THREADED_CONVERT_SWSCALE = (9, 7)
_THREADED_CONVERT_FORMATS = frozenset({"yuv420p", "nv12"})

_VIDEOTOOLBOX = ("h264_videotoolbox", "hevc_videotoolbox")


def _on_ios() -> bool:
    return sys.platform.startswith("ios") or os.path.exists("/var/mobile")


class _WriterStream:
    """A partial movie's video stream, as the writer thread uses it.

    Two things on top of the stream's own encode():

    * Frames are converted to the encoder's pixel format on several cores
      first. PyAV does it inside encode() with the encoder's thread count,
      which VideoToolbox leaves at one: 37 ms for an 8K frame on one core,
      on the writer thread, ahead of the hardware encoder's own 55 ms. Same
      call, same bytes (where that was checked, see _writer_stream); the
      encoder, its options and the frames it gets are unchanged.
    * Frames are numbered here (PyAV numbered them by count), so a held
      picture can be written as its first and last frame with the time
      between them skipped (hold), instead of every frame of it encoded
      again.

    Everything else is the stream's own.
    """

    __slots__ = ("_stream", "_threads", "_next_pts", "_capped")

    def __init__(self, stream: Any, threads: int, capped: bool = False) -> None:
        object.__setattr__(self, "_stream", stream)
        object.__setattr__(self, "_threads", threads)
        object.__setattr__(self, "_next_pts", 0)
        # VideoToolbox here waits once a few frames are being encoded
        # (max_pending_frames): frames may go back to the camera.
        object.__setattr__(self, "_capped", capped)

    def encode(self, frame: Any = None) -> Any:
        stream = self._stream
        if frame is not None:
            if self._threads > 1:
                pix_fmt = stream.pix_fmt
                if (
                    frame.format.name != pix_fmt
                    and frame.width == stream.width
                    and frame.height == stream.height
                ):
                    # What PyAV's encode() calls, plus the threads.
                    frame = frame.reformat(format=pix_fmt, threads=self._threads)
            if frame.pts is None:
                frame.pts = self._next_pts  # in the stream's 1/fps, as PyAV's own
            object.__setattr__(self, "_next_pts", frame.pts + 1)
        return stream.encode(frame)

    def hold(self, frames: int) -> None:
        """The next frame comes ``frames`` frame times later than it would."""
        object.__setattr__(self, "_next_pts", self._next_pts + int(frames))

    def __getattr__(self, name: str) -> Any:
        return getattr(self._stream, name)

    def __setattr__(self, name: str, value: Any) -> None:
        setattr(self._stream, name, value)

    def __repr__(self) -> str:
        return f"<writer stream {self._stream!r}, converting on {self._threads} threads>"
def _writer_stream(stream: Any, capped: bool = False) -> Any:
    """``stream`` in a _WriterStream; frames converted on threads where exact."""
    threads = 1
    try:
        from manim.utils.ios_encoder import settings as _settings

        wanted = _settings.frame_convert_threads()
        swscale = tuple(av.library_versions.get("libswscale", (0, 0, 0)))[:2]
        if (
            wanted > 1
            and swscale >= _THREADED_CONVERT_SWSCALE
            and int(stream.width) % 2 == 0
            and int(stream.height) % 2 == 0
            and stream.pix_fmt in _THREADED_CONVERT_FORMATS
        ):
            threads = wanted
    except Exception:
        pass
    try:
        return _WriterStream(stream, threads, capped)
    except Exception:
        return stream
@functools.lru_cache(maxsize=None)
def _caps_pending_frames(codec: str) -> bool:
    """Whether this FFmpeg's ``codec`` takes max_pending_frames: python-ios-
    lib's build of the VideoToolbox encoders (ffmpeg_ios/), not stock FFmpeg."""
    try:
        options = av.codec.Codec(codec, "w").descriptor.options
        return any(option.name == "max_pending_frames" for option in options)
    except Exception:
        return False
def _pool_budget_bytes() -> int:
    try:
        from manim.utils.ios_encoder import settings as _settings

        return max(0, int(_settings.frame_queue_budget_mb)) * 1024 * 1024
    except Exception:
        return 256 * 1024 * 1024
def _encoder_pending_frames() -> int:
    try:
        from manim.utils.ios_encoder import settings as _settings

        return max(0, int(_settings.encoder_pending_frames or 0))
    except Exception:
        return 0


def _holds_written_once(stream: Any = None, gif: bool | None = None) -> bool:
    """Whether a held frame is written as its first and last frame.

    Only for VideoToolbox, where it was checked: it does not reorder frames,
    so the clips join with the right times. An encoder that does (libx264's
    B-frames) came out short across a hold once the clips were joined, and
    keeps writing every frame. A GIF is made by decoding the partial movies
    and numbering the frames again, which would drop the time in between,
    so a GIF keeps them all too. The writer says whether its output is a GIF;
    without ``gif``, ``config.format`` does, as in manim 0.20.
    """
    if gif is None:
        gif = str(config.get("format", "") or "").lower() == "gif"
    if gif:
        return False
    if stream is not None:
        codec = getattr(getattr(stream, "codec_context", None), "name", "") or ""
        if not str(codec).endswith("_videotoolbox"):
            return False
    try:
        from manim.utils.ios_encoder import settings as _settings

        return _settings.hold_frames_once()
    except Exception:
        return True


def _return_frame(frame: Any, stream: Any = None) -> bool:
    """Gives a frame the writer is done with back to the camera to draw the
    next one in (camera._FramePool), unless anything else still holds it —
    a hook that kept the array, a GIF collector — so a kept frame is never
    drawn over.

    Only while ``stream`` caps the frames VideoToolbox holds: drawn faster,
    frames would otherwise pile up inside the encoder (10 at once instead of
    6 at 8K in the app, ~400 MB). And only for frames within the frame
    queue's memory budget (settings.frame_queue_budget_mb, 256 MB: up to
    8K): the frame kept for the camera can be one more alive at a time, and
    at 14K (462 MB a frame) that was ~330 MB more at the peak, where at 8K
    the encoder's cap saves more than it costs.
    OFFLINAI_MANIM_FRAME_POOL=0 never gives frames back, =1 always does.
    """
    mode = os.environ.get("OFFLINAI_MANIM_FRAME_POOL", "")
    if mode == "0":
        return False
    if not isinstance(frame, np.ndarray):
        return False
    if mode != "1" and (
        not getattr(stream, "_capped", False) or frame.nbytes > _pool_budget_bytes()
    ):
        return False
    from ..camera import camera as _camera

    if not _camera._unshared(frame):
        return False
    return _camera._frame_pool.give_back(frame)
def _clip_has_video(path: str) -> bool:
    try:
        if os.path.getsize(path) == 0:
            return False
        with av.open(path) as container:
            if not container.streams.video:
                return False
            stream = container.streams.video[0]
            return any(packet.size for packet in container.demux(stream))
    except Exception:
        return False
def _clip_encoding(path: str) -> tuple:
    """What two clips must share to be joined packet for packet."""
    with av.open(path) as container:
        context = container.streams.video[0].codec_context
        return (context.name, context.width, context.height,
                context.format.name if context.format else "",
                bytes(context.extradata or b""))


def _write_every_frame(path: str, rate: Any) -> None:
    """Rewrites a clip at a constant frame rate: each decoded frame repeated
    until the next one is due (its time stamps say when)."""
    rate = to_av_frame_rate(rate)
    shots: list[tuple[int, Any, str]] = []
    with av.open(path) as source:
        stream = source.streams.video[0]
        codec = stream.codec_context.name
        width, height = stream.width, stream.height
        first = None
        for frame in source.decode(stream):
            if first is None:
                first = frame.pts
            at = int(round(float((frame.pts - first) * frame.time_base * rate)))
            shots.append((at, frame.to_ndarray(), frame.format.name))
    if not shots:
        return
    total = shots[-1][0] + 1
    tmp = path + ".every.mov"
    encoders = [(codec, {"realtime": "1", "g": str(int(rate) or 1)}, "yuv420p"),
                ("mpeg4", {"flags": "+qscale", "global_quality": "236"}, "yuv420p"),
                ("mjpeg", {"flags": "+qscale", "global_quality": "236"}, "yuvj420p")]
    for name, options, pix_fmt in encoders:
        try:
            container = av.open(tmp, mode="w", format="mov")
            out = container.add_stream(name, rate=rate, options=options)
            out.width, out.height, out.pix_fmt = width, height, pix_fmt
            out.codec_context.open()
        except Exception:
            try:
                container.close()
            except Exception:
                pass
            continue
        try:
            k = 0
            for index in range(total):
                while k + 1 < len(shots) and shots[k + 1][0] <= index:
                    k += 1
                _at, pixels, fmt = shots[k]
                frame = av.VideoFrame.from_ndarray(pixels, format=fmt)
                frame.pts = index
                for packet in out.encode(frame):
                    container.mux(packet)
            for packet in out.encode():
                container.mux(packet)
        finally:
            container.close()
        os.replace(tmp, path)
        return
    raise RuntimeError("no encoder could be opened")


def convert_audio(
    input_path: Path, output_path: Path | _TemporaryFileWrapper[bytes], codec_name: str
) -> None:
    with (
        av.open(input_path) as input_audio,
        av.open(output_path, "w") as output_audio,
    ):
        input_audio_stream = input_audio.streams.audio[0]
        output_audio_stream = output_audio.add_stream(codec_name)
        for frame in input_audio.decode(input_audio_stream):
            for packet in output_audio_stream.encode(frame):
                output_audio.mux(packet)

        for packet in output_audio_stream.encode():
            output_audio.mux(packet)
def _webm_audio_codec() -> str:
    """Return the audio codec used for sound in a VP9 (webm) video.

    ``libvorbis`` is preferred, but PyAV wheels are not always built with it
    (for example some Windows builds only ship the experimental native
    ``vorbis`` encoder). Fall back to ``libopus``, which webm also supports.
    """
    try:
        av.codec.Codec("libvorbis", "w")
    except ValueError:
        return "libopus"
    return "libvorbis"
class _ClipEncoding:
    """One partial movie file's writer thread, its queue, and how far it got.

    Each clip's thread reads its own queue, not ``self.queue``: a thread that
    outlived its clip used to pull frames from the next clip's queue, because
    it looked the queue up through the writer. And it records every frame it
    encodes, so ``close_partial_movie_stream`` can tell a slow encoder (8K at
    120 fps, a deep queue, a minute and more of backlog) from one that has
    stopped, rather than deciding by the clock alone.
    """

    __slots__ = ("queue", "closing", "queued", "encoded", "error")

    def __init__(self, queue: Queue) -> None:
        self.queue = queue
        #: Set by ``close_partial_movie_stream``: once the queue is empty, the
        #: thread is done, even if its sentinel never arrives — a host app's
        #: Stop button may have drained the queue, sentinel and all.
        self.closing = Event()
        #: Frames handed to the queue (the render thread counts these).
        self.queued = 0
        #: Frames encoded (the writer thread counts these).
        self.encoded = 0
        #: What stopped the writer thread, if something did.
        self.error: BaseException | None = None

    @property
    def left(self) -> int:
        return max(self.queued - self.encoded, 0)
@dataclass(frozen=True, slots=True)
class _SceneFileWriterSettings:
    """Immutable inputs consumed by one :class:`SceneFileWriter`.

    The settings contain resolved output paths and segment encoding, bounded
    encoder-pool limits, cache maintenance, and the sound-asset search root.
    """

    plan: OutputPlan
    video_encoder: VideoEncoderSpec | None
    max_inflight_encoders: int
    encoder_queue_size: int
    max_files_cached: int
    assets_dir: Path

    def __post_init__(self) -> None:
        output = self.plan.output
        if output.is_video != (self.video_encoder is not None):
            raise ValueError(
                "Video output and resolved video encoder settings must be provided together.",
            )
        expected_segment_extension = (
            output.segment_extension if output.is_video else None
        )
        if self.plan.segment_extension != expected_segment_extension:
            raise ValueError(
                "The output plan segment extension does not match its output specification.",
            )
        if (
            self.video_encoder is not None
            and f".{self.video_encoder.container_format}" != expected_segment_extension
        ):
            raise ValueError(
                "The video encoder container does not match the output plan.",
            )
        if self.max_inflight_encoders <= 0:
            raise ValueError("max_inflight_encoders must be positive.")
        if self.encoder_queue_size <= 0:
            raise ValueError("encoder_queue_size must be positive.")
        if self.max_files_cached < -1:
            raise ValueError("max_files_cached must be non-negative or -1.")
        if not self.assets_dir.is_absolute():
            raise ValueError("assets_dir must be absolute.")


class SceneFileWriter:
    """Coordinate a scene's clips and assemble its media artifacts.

    Upstream manim 0.22.1's writer, with python-ios-lib's encoding engine:

    * **One clip at a time, on a writer thread of its own** (``listen_and_write``),
      fed through a queue bounded for the device's memory
      (:mod:`manim.utils.ios_encoder` ``settings.frame_queue_depth``), not
      0.22's pool of concurrent segment jobs: two VideoToolbox sessions at
      once were slower on an iPad and cost gigabytes.
    * **VideoToolbox** on iOS (H.264, or HEVC tagged ``hvc1`` above H.264's
      size), with ``realtime``, a one-second GOP and python-ios-lib's
      ``max_pending_frames``; mpeg4 if the encoder can't open.
    * Frames converted to YUV on several threads (``_WriterStream``), a
      ``wait()`` written as its first and last frame on VideoToolbox, frames
      given back to the camera's pool once encoded, a close that waits for as
      long as the encoder makes progress and fails loudly when it stops, and
      PyAV's buffers released after each clip on iOS.

    It also keeps manim 0.20's seams, which ManimStudio and CodeBench patch:
    ``write_frame(frame, num_frames)`` called positionally,
    ``encode_and_write_frame``, ``video_stream`` / ``video_container`` /
    ``partial_movie_file_path`` / ``queue`` while a clip is open,
    ``renderer`` (set by the renderer), ``combine_files``, and this module's
    ``to_av_frame_rate``.

    Ownership of each array passed to :meth:`write_frame` transfers to the
    writer; callers must not mutate or reuse it afterward.

    Parameters
    ----------
    settings
        Resolved output, encoding, pool, cache, and asset-search settings.

    Attributes
    ----------
    sections
        Ordered section metadata for the scene.
    partial_movie_files
        Segment paths in animation order, including ``None`` for skipped plays.
    """

    def __init__(self, settings: _SceneFileWriterSettings) -> None:
        self.settings = settings
        self.output_spec = settings.plan.output
        self.output_plan = settings.plan
        self.video_encoder = settings.video_encoder
        #: The renderer writing through this writer; the renderer sets it.
        #: Host apps read ``renderer.num_plays`` from it, as in manim 0.20.
        self.renderer: Any = None
        # The clip being written, while one is open (open_partial_movie_stream).
        self.partial_movie_file_path: Path | None = None
        self.video_container: Any = None
        self.video_stream: Any = None
        self.queue: Queue[tuple[int, RGBAPixelArray | None]] | None = None
        self.writer_thread: Thread | None = None
        self._clip_encoding: _ClipEncoding | None = None
        self.animation_index: int | None = None
        self._stall_limit: int = 0
        self._stall_reason = ""
        self.init_audio()
        self.frame_count = 0
        self.partial_movie_files: list[str | None] = []
        self.subcaptions: list[srt.Subtitle] = []
        self.sections: list[Section] = []
        # first section gets automatically created for convenience
        # if you need the first section to be skipped, add a first section by hand, it will replace this one
        self.next_section(
            name="autocreated", type_=DefaultSectionType.NORMAL, skip_animations=False
        )

    @property
    def output_name(self) -> Path:
        """Return the planned logical output stem as a compatibility view."""
        return Path(self.output_plan.output_stem)
    @property
    def image_file_path(self) -> Path:
        """Return the planned still or video-fallback image path."""
        if self.output_spec.is_image_sequence:
            return self.image_sequence_directory.with_suffix(".png")
        path = (
            self.output_plan.primary_artifact
            if self.output_spec.is_still
            else self.output_plan.fallback_image
        )
        if path is None:
            raise AttributeError("This output plan does not contain an image path.")
        return path
    @property
    def image_sequence_directory(self) -> Path:
        """Return the planned PNG-sequence directory."""
        path = self.output_plan.image_sequence_dir
        if path is None:
            raise AttributeError("This output plan does not contain an image sequence.")
        return path
    @property
    def movie_file_path(self) -> Path:
        """Return the planned primary video artifact path."""
        if not self.output_spec.is_video or self.output_plan.primary_artifact is None:
            raise AttributeError("This output plan does not contain a video artifact.")
        return self.output_plan.primary_artifact
    @property
    def gif_file_path(self) -> Path:
        """Return the planned GIF artifact path."""
        if not self.output_spec.is_gif:
            raise AttributeError("This output plan does not contain a GIF artifact.")
        return self.movie_file_path
    @property
    def sections_output_dir(self) -> Path:
        """Return the planned sections directory, or the legacy empty path."""
        return self.output_plan.sections_dir or Path("")
    @property
    def partial_movie_directory(self) -> Path:
        """Return the planned silent-segment cache directory."""
        path = self.output_plan.segment_cache_dir
        if path is None:
            raise AttributeError("This output plan does not contain video segments.")
        return path
    def finish_last_section(self) -> None:
        """Delete current section if it is empty."""
        if len(self.sections) and self.sections[-1].is_empty():
            self.sections.pop()
    def next_section(self, name: str, type_: str, skip_animations: bool) -> None:
        """Create segmentation cut here."""
        self.finish_last_section()

        # images don't support sections
        section_video: str | None = None
        # don't save when None
        if self.output_spec.save_sections and not skip_animations:
            section_path = self.output_plan.section_path(len(self.sections), name)
            assert self.output_plan.sections_dir is not None
            # Section stores paths relative to its index file.
            section_video = section_path.relative_to(
                self.output_plan.sections_dir,
            ).as_posix()

        self.sections.append(
            Section(
                type_,
                section_video,
                name,
                skip_animations,
            ),
        )
    def add_partial_movie_file(self, hash_animation: str | None) -> None:
        """Append a planned segment path to the writer and current section.

        The list retains one entry per animation so explicit animation indices
        select the corresponding segment.

        Parameters
        ----------
        hash_animation
            Hash of the animation.
        """
        if not self.output_spec.is_video:
            return

        # Skipped animations retain a placeholder to preserve index alignment.
        if hash_animation is None:
            self.partial_movie_files.append(None)
            self.sections[-1].partial_movie_files.append(None)
        else:
            new_partial_movie_file = str(self.output_plan.segment_path(hash_animation))
            self.partial_movie_files.append(new_partial_movie_file)
            self.sections[-1].partial_movie_files.append(new_partial_movie_file)
    def init_audio(self) -> None:
        """Preps the writer for adding audio to the movie."""
        self.includes_sound = False
    def create_audio_segment(self) -> None:
        """Creates an empty, silent, Audio Segment."""
        self.audio_segment = AudioSegment.silent()
    def add_audio_segment(
        self,
        new_segment: AudioSegment,
        time: float | None = None,
        gain_to_background: float | None = None,
    ) -> None:
        """This method adds an audio segment from an AudioSegment type object
        and suitable parameters.

        Parameters
        ----------
        new_segment
            The audio segment to add

        time
            the timestamp at which the sound should be added.

        gain_to_background
            The gain of the segment from the background.
        """
        if not self.includes_sound:
            self.includes_sound = True
            self.create_audio_segment()
        segment = self.audio_segment
        curr_end = segment.duration_seconds
        if time is None:
            time = curr_end
        if time < 0:
            raise ValueError("Adding sound at timestamp < 0")

        new_end = time + new_segment.duration_seconds
        diff = new_end - curr_end
        if diff > 0:
            segment = segment.append(
                AudioSegment.silent(int(np.ceil(diff * 1000))),
                crossfade=0,
            )
        self.audio_segment = segment.overlay(
            new_segment,
            position=int(1000 * time),
            gain_during_overlay=gain_to_background,
        )
    def add_sound(
        self,
        sound_file: StrPath,
        time: float | None = None,
        gain: float | None = None,
        **kwargs: Any,
    ) -> None:
        """This method adds an audio segment from a sound file.

        Parameters
        ----------
        sound_file
            The path to the sound file.

        time
            The timestamp at which the audio should be added.

        gain
            The gain of the given audio segment.

        **kwargs
            This method uses add_audio_segment, so any keyword arguments
            used there can be referenced here.

        """
        file_path = get_full_sound_file_path(sound_file, self.settings.assets_dir)
        # we assume files with .wav / .raw suffix are actually
        # .wav and .raw files, respectively.
        if file_path.suffix not in (".wav", ".raw"):
            # we need to pass delete=False to work on Windows
            # TODO: figure out a way to cache the wav file generated (benchmark needed)
            with NamedTemporaryFile(suffix=".wav", delete=False) as wav_file_path:
                convert_audio(file_path, wav_file_path, "pcm_s16le")
                new_segment = AudioSegment.from_file(wav_file_path.name)
                logger.info(f"Automatically converted {file_path} to .wav")
            Path(wav_file_path.name).unlink()
        else:
            new_segment = AudioSegment.from_file(file_path)

        if gain:
            new_segment = new_segment.apply_gain(gain)
        self.add_audio_segment(new_segment, time, **kwargs)

    # Writers
    def begin_animation(
        self,
        allow_write: bool = False,
        file_path: StrPath | None = None,
        *,
        animation_index: int | None = None,
    ) -> None:
        """Open the animation's clip when video writing is enabled.

        Parameters
        ----------
        allow_write
            Whether this animation needs a new segment.
        file_path
            Explicit segment target, or ``None`` to use the planned cache path.
        animation_index
            Scene-local animation index used to select and label the segment.
        """
        if self.output_spec.is_video and allow_write:
            self.open_partial_movie_stream(
                file_path=file_path,
                animation_index=animation_index,
            )

    def end_animation(self, allow_write: bool = False) -> None:
        """Seal the current segment job when video writing is enabled.

        Parameters
        ----------
        allow_write
            Whether the current animation has an open segment job.
        """
        if self.output_spec.is_video and allow_write:
            self.close_partial_movie_stream()

    def write_frame(
        self,
        pixels: RGBAPixelArray,
        num_frames: int = 1,
        *,
        repeat: int | None = None,
    ) -> None:
        """Take ownership of one top-left C-contiguous ``uint8`` RGBA frame,
        shown for ``num_frames`` frames (0.22 calls it ``repeat``).

        The renderer passes the count positionally, as manim 0.20 did: host
        apps replace this method with a ``(frame, num_frames=1)`` wrapper.
        The caller must not mutate or reuse ``pixels`` after this method
        returns because video encoding consumes the array asynchronously.
        """
        count = int(num_frames if repeat is None else repeat)
        if self.output_spec.is_video:
            clip = self._clip_encoding
            if clip is not None:
                # Presentation rendering can emit frames outside an open
                # segment; such frames do not belong to file output.
                self._put_frame(clip, (count, pixels))
                clip.queued += count

        if self.output_spec.is_image_sequence:
            self.output_image(Image.fromarray(pixels))

    def _put_frame(self, clip: _ClipEncoding, item: tuple[int, Any]) -> None:
        """Queue a frame for the writer thread.

        The queue is bounded, so this waits while the encoder is behind, for
        as long as it keeps encoding. It stops the render instead of waiting
        for good when the encoder has failed, its thread has exited, or no
        frame has come out for the stall window -- the same rule as the wait
        at the clip's close, which a renderer blocked here never reached.
        """
        seen = clip.encoded
        stalled = 0.0
        while True:
            if clip.error is not None:
                raise RuntimeError(
                    f"the video encoder stopped: {type(clip.error).__name__}: "
                    f"{clip.error}"
                ) from clip.error
            started = time.monotonic()
            try:
                clip.queue.put(item, timeout=0.5)
                return
            except Full:
                thread = self.writer_thread
                if clip.error is None and (thread is None or not thread.is_alive()):
                    raise RuntimeError(
                        "the video encoder stopped: its writer thread has exited"
                    ) from None
                if clip.encoded != seen:
                    seen = clip.encoded
                    stalled = 0.0
                    continue
                # A slice far longer than asked for means the process was
                # suspended (iOS in the background): a pause, not a stall.
                stalled += min(time.monotonic() - started, 1.5)
                limit = self._stall_limit
                if limit and stalled >= limit:
                    spec = self.video_encoder
                    raise RuntimeError(
                        f"the video encoder made no progress for {int(stalled)} s at "
                        f"{spec.width}x{spec.height} ({clip.left} frame(s) still "
                        f"queued; the limit is {limit} s, {self._stall_reason} — "
                        f"settings.encoder_stall_seconds or "
                        f"OFFLINAI_MANIM_ENCODER_STALL_S changes it)"
                    )

    def output_image(self, image: Image.Image) -> None:
        file_path = self.output_plan.image_frame_path(self.frame_count)
        file_path.parent.mkdir(parents=True, exist_ok=True)
        image.save(file_path)
        self.frame_count += 1

    def save_image(self, pixels: RGBAPixelArray) -> None:
        """Save one RGBA frame to the planned still-image path."""
        if not self.output_spec.enabled:
            return
        self.image_file_path.parent.mkdir(parents=True, exist_ok=True)
        try:
            Image.fromarray(pixels).save(self.image_file_path)
        except Exception as error:
            # The video is what a render is for; a still that can't be saved
            # (an image codec missing from a build) is logged, not fatal.
            if not _on_ios():
                raise
            logger.warning(f"skipped save_image (iOS): {type(error).__name__}: {error}")
            return
        self.print_file_ready_message(self.image_file_path)

    def finish(self) -> None:
        """Assemble the configured time-based output from the written clips."""
        # Every clip is written: the frames kept for the camera to reuse
        # (camera._FramePool) are not needed any more.
        from ..camera import camera as _camera

        _camera._frame_pool.clear()
        if self.output_spec.is_video:
            self.join_all_encode_jobs()
            self.combine_to_movie()
            if self.output_spec.save_sections:
                self.combine_to_section_videos()
            # Cache cleanup runs after the in-flight encode jobs have been drained.
            prune_segment_cache(
                self.partial_movie_directory,
                self.settings.max_files_cached,
            )
            self._drop_segments_on_ios()
        elif self.output_spec.is_image_sequence:
            target_dir = self.image_sequence_directory
            self.final_file_path = target_dir
            logger.info("\n%i images ready at %s\n", self.frame_count, str(target_dir))
        if self.subcaptions:
            self.write_subcaption_file()

    def _drop_segments_on_ios(self) -> None:
        """The scene's clips go once the movie is made when ``flush_cache`` is
        set, as manim 0.20 did here (0.22 removed the option; python-ios-lib's
        ``_config`` still sets it on iOS, where caching is off, so nothing
        reads the clips again, and long scenes wrote hundreds of megabytes of
        them). ``config.flush_cache = False`` keeps them."""
        if not getattr(config, "flush_cache", False):
            return
        for path in {p for p in self.partial_movie_files if p}:
            with suppress(OSError):
                Path(path).unlink(missing_ok=True)

    def _animation_index(self, animation_index: int | None) -> int:
        if animation_index is not None:
            return animation_index
        # A host app's own call, as manim 0.20 made it.
        try:
            return int(self.renderer.num_plays)
        except Exception:
            return len([p for p in self.partial_movie_files if p is not None]) - 1

    def _stream_settings(self) -> tuple[str, str, dict[str, str], str | None]:
        """The clip's encoder, pixel format, options and mp4 tag: the resolved
        spec's, and on iOS VideoToolbox's own.

        On iOS the encoder is asked for here, at the clip's open, as manim 0.20
        did: a host app configures ``manim.utils.ios_encoder.settings`` (its
        codec, its queue) after the scene, and so the spec, was made.
        """
        spec = self.video_encoder
        assert spec is not None
        codec, pix_fmt = spec.codec, spec.pixel_format
        options = dict(spec.options)
        tag: str | None = None
        if _on_ios() and str(config.video_codec or "auto") == "auto" \
                and not self.output_spec.transparent and spec.container_format in ("mp4", "mov"):
            from manim.utils.ios_encoder import settings as _ios_settings

            # Re-read the environment: a host app usually configures the
            # render after the interpreter is already up, and `os.environ` is
            # a snapshot taken when `os` was imported.
            _ios_settings.refresh()
            codec, tag = _ios_settings.codec_for(spec.width, spec.height)
            pix_fmt = "yuv420p"
            options = {}
        if codec in _VIDEOTOOLBOX:
            # realtime=1 encodes each frame as it arrives (no lookahead
            # buffer). realtime=0 asks VideoToolbox to hold multiple frames
            # for quality optimization, which on iOS leaks hundreds of MB per
            # long animation.
            options.setdefault("realtime", "1")
            # Keyframe every second; smaller GOPs mean fewer reference
            # frames retained by the encoder between keyframes.
            options.setdefault("g", str(max(int(round(float(spec.frame_rate))), 1)))
            # python-ios-lib's FFmpeg: wait once this many frames are being
            # encoded, rather than let VideoToolbox queue a copy of every
            # frame the writer hands it (see _return_frame).
            pending = _encoder_pending_frames()
            if pending and _caps_pending_frames(codec):
                options["max_pending_frames"] = str(pending)
            if codec.startswith("hevc") and tag is None:
                tag = "hvc1"
        return codec, pix_fmt, options, tag

    def open_partial_movie_stream(
        self,
        file_path: StrPath | None = None,
        *,
        animation_index: int | None = None,
    ) -> None:
        """Open the container and video stream of one animation's clip, and
        start its writer thread."""
        # The stream, container and queue below replace the previous clip's,
        # which its writer thread reads (encode_and_write_frame uses
        # self.video_stream and self.video_container). Only a thread that has
        # exited may lose them; close_partial_movie_stream waits for that.
        previous = self.writer_thread
        if previous is not None and previous.is_alive():
            raise RuntimeError(
                "the previous animation's video encoder is still running; "
                "the next clip can't open until it has finished")
        animation_index = self._animation_index(animation_index)
        if file_path is None:
            file_path = self.partial_movie_files[animation_index]
            if file_path is None:
                raise RuntimeError(
                    "open_partial_movie_stream() called for a play that has no "
                    "partial movie file path.",
                )
        file_path = Path(file_path)
        file_path.parent.mkdir(parents=True, exist_ok=True)
        self.partial_movie_file_path = file_path
        self.animation_index = animation_index

        spec = self.video_encoder
        if spec is None:
            raise RuntimeError("Video segment encoding requires resolved settings.")
        width, height, fps = spec.width, spec.height, spec.frame_rate
        codec, pix_fmt, options, tag = self._stream_settings()

        print(f"[manim-debug] open_partial_movie_stream: path={file_path}",
              flush=True)
        print(f"[manim-debug]   codec={codec} pix_fmt={pix_fmt} "
              f"fps={fps} size={width}x{height}", flush=True)
        video_container = av.open(str(file_path), mode="w", format=spec.container_format)
        try:
            stream = video_container.add_stream(codec, rate=fps, options=options)
        except Exception as error:
            print(f"[manim-debug]   add_stream({codec}) failed: "
                  f"{type(error).__name__}: {error}", flush=True)
            if codec == "mpeg4":
                video_container.close()
                raise
            # The chosen encoder isn't in this FFmpeg (or won't open at this
            # size): mpeg4 always is, and finishes, slowly.
            logger.warning(f"Codec {codec} unavailable, falling back to mpeg4")
            video_container.close()
            video_container = av.open(str(file_path), mode="w", format=spec.container_format)
            stream = video_container.add_stream("mpeg4", rate=fps)
            codec, pix_fmt, options, tag = "mpeg4", "yuv420p", {}, None
        stream.pix_fmt = pix_fmt
        stream.width = width
        stream.height = height
        if tag and codec.startswith("hevc"):
            # ffmpeg defaults HEVC in mp4 to `hev1`, which is legal and which
            # AVFoundation and QuickTime both refuse to play.
            try:
                stream.codec_tag = tag
            except Exception as tag_error:
                print(f"[manim-debug]   codec_tag {tag} rejected: "
                      f"{type(tag_error).__name__}: {tag_error}", flush=True)

        self.video_container = video_container
        self.video_stream = _writer_stream(
            stream, capped="max_pending_frames" in options and codec in _VIDEOTOOLBOX)

        # The queue is bounded by bytes on iOS (settings.frame_queue_depth: a
        # fixed 32 frames was 256 MB at 1080p and 4.25 GB at 8K), and by
        # 0.22's encoder_queue_size elsewhere.
        frame_bytes = max(int(width) * int(height) * 4, 1)
        from manim.utils.ios_encoder import settings as _q_settings

        q_max, q_reason = _q_settings.refresh().frame_queue_depth(width, height)
        if not _on_ios() and q_reason != "set explicitly":
            q_max, q_reason = self.settings.encoder_queue_size, "encoder_queue_size"
        self._stall_limit, self._stall_reason = _q_settings.encoder_stall_window(
            width, height)
        print(f"[manim] frame queue: "
              f"{'unbounded' if q_max == 0 else str(q_max) + ' frames'} "
              f"({frame_bytes / 1e6:.1f} MB each"
              + (f", {q_max * frame_bytes / 1e6:.0f} MB held" if q_max else "")
              + f") — {q_reason}", flush=True)
        self.queue = Queue(maxsize=q_max)
        # The thread gets this clip's queue and progress as its own, so it can
        # never read the next clip's queue, however late it runs. A daemon: a
        # render that fails in a way nothing aborts must not keep the process
        # alive waiting on a queue no one will fill.
        self._clip_encoding = _ClipEncoding(self.queue)
        self.writer_thread = Thread(
            target=self.listen_and_write,
            args=(self._clip_encoding,),
            name=f"partial-movie-encoder-{animation_index}",
            daemon=True,
        )
        self.writer_thread.start()

    def listen_and_write(self, clip: _ClipEncoding | None = None) -> None:
        """For internal use only: blocks until new frame is available on the queue.

        [manim-debug] Wraps encode_and_write_frame in try/except so a
        silent PyAV/VideoToolbox exception in this background thread
        shows up in stdout instead of killing the thread invisibly —
        the classic "only first frame rendered" symptom on iOS.

        ``clip`` is the partial movie file this thread writes, which
        ``open_partial_movie_stream`` passes in. Its queue is read rather than
        ``self.queue``, so a thread can never take the next clip's frames.
        """
        queue = clip.queue if clip is not None else self.queue
        _mdbg_count = 0
        while True:
            if clip is None:
                num_frames, frame_data = queue.get()
            else:
                try:
                    num_frames, frame_data = queue.get(timeout=0.5)
                except Empty:
                    # Everything queued is encoded and the clip is closing.
                    # The sentinel may never come: a host app's Stop can drain
                    # the queue, sentinel included (ManimStudio's does).
                    if clip.closing.is_set():
                        print(f"[manim-debug] listen_and_write: queue empty at close, "
                              f"exiting after {_mdbg_count} encoded batches",
                              flush=True)
                        break
                    continue
            if frame_data is None:
                print(f"[manim-debug] listen_and_write: got sentinel, "
                      f"exiting after {_mdbg_count} encoded batches",
                      flush=True)
                break

            try:
                if clip is None:
                    self.encode_and_write_frame(frame_data, num_frames)
                elif num_frames >= 3 and _holds_written_once(self.video_stream, gif=self.output_spec.is_gif):
                    self._write_held_frame(frame_data, num_frames, clip)
                else:
                    # A frame at a time, so that the wait at the clip's close
                    # sees the encoder move through a long hold — a wait() is
                    # one batch of hundreds of frames — and not only between
                    # batches.
                    for _ in range(num_frames):
                        self.encode_and_write_frame(frame_data, 1)
                        clip.encoded += 1
                _mdbg_count += 1
                if clip is not None:
                    _return_frame(frame_data, self.video_stream)
                # Only log every 15 frames to avoid spamming at 30fps.
                if _mdbg_count in (1, 2, 3, 5, 10) or _mdbg_count % 15 == 0:
                    try:
                        qlen = queue.qsize()
                    except Exception:
                        qlen = -1
                    print(f"[manim-debug] encoded batch #{_mdbg_count} "
                          f"(×{num_frames} frames, queue depth {qlen})",
                          flush=True)
            except BaseException as e:
                # Catch BaseException — SystemExit / KeyboardInterrupt
                # in a worker thread would also kill the writer silently.
                import traceback as _tb
                print(f"[manim-debug] ! encode CRASH on batch #{_mdbg_count + 1}: "
                      f"{type(e).__name__}: {e}", flush=True)
                print("[manim-debug] traceback:", flush=True)
                _tb.print_exc()
                if clip is not None:
                    clip.error = e
                # Drain any remaining frames from the queue so the main
                # thread's .put() calls don't block forever — otherwise
                # the whole render hangs instead of failing cleanly.
                while True:
                    try:
                        queue.get_nowait()
                    except Exception:
                        break
                break
    def _write_held_frame(
        self, frame: PixelArray, num_frames: int, clip: _ClipEncoding
    ) -> None:
        """Writes a frame shown for ``num_frames`` frames (a wait()) as two.

        Every frame of a hold used to be converted and encoded again: at 8K
        each one costs the hardware encoder about 55 ms, and wait() holds
        are often half of a video's frames. The first frame is written, the
        time stamps skip ahead, and the last one is written, so the picture
        is on screen for the same time and the clip is as long as before.
        The movie is variable frame rate across a hold.

        If the stream is replaced while doing it (ManimStudio's encoder
        wrapper moves an animation to a new clip when iOS takes the hardware
        encoder away), the rest of the hold is written frame by frame into
        the new clip, as it would have been.
        """
        stream = self.video_stream
        self.encode_and_write_frame(frame, 1)
        written = 1
        if self.video_stream is stream and hasattr(stream, "hold"):
            stream.hold(num_frames - 2)
            self.encode_and_write_frame(frame, 1)
            written = num_frames
            if self.video_stream is not stream:
                # The last frame went to a new clip; the old one ends after
                # the first, so the frames in between are written again.
                written = 2
            else:
                self.__dict__.setdefault("_held_clips", set()).add(
                    str(self.partial_movie_file_path)
                )
        for _ in range(num_frames - written):
            self.encode_and_write_frame(frame, 1)
        clip.encoded += num_frames
    def _fill_holds_before_reencoding(self, clip_paths: list[Any]) -> None:
        """Writes every frame of the holds back into a scene's clips when the
        clips are about to be decoded and encoded again to join them.

        A hold written as its first and last frame keeps its time when clips
        are joined packet for packet, which is the normal case. ManimStudio's
        encoder wrapper, when iOS takes the hardware encoder away, moves the
        animation to a new clip (it records them in ``_ms_segments``), and if
        the clips then differ in encoding it joins them by decoding every
        frame and numbering the frames one by one, which would shrink a hold
        to its two frames. Only in that case are the hold clips written out
        frame by frame here first; then any join keeps their length.
        """
        held = self.__dict__.get("_held_clips")
        segments = getattr(self, "_ms_segments", None)
        if not held or not segments:
            return
        clips = [str(p) for p in clip_paths]
        joined = [
            c
            for p in clips
            for c in [p, *segments.get(p, [])]
            if _clip_has_video(c)
        ]
        if len({_clip_encoding(c) for c in joined}) <= 1:
            return  # joined packet for packet: the holds keep their times
        for path in clips:
            if path in held:
                try:
                    _write_every_frame(path, getattr(getattr(self, "video_encoder", None), "frame_rate", None) or config.frame_rate)
                    held.discard(path)
                except Exception as error:
                    print(f"[manim] a held frame could not be written out in "
                          f"{os.path.basename(path)}: {type(error).__name__}: "
                          f"{error}", flush=True)
    def encode_and_write_frame(self, frame: PixelArray, num_frames: int) -> None:
        """For internal use only: takes a given frame in ``np.ndarray`` format and
        writes it to the stream
        """
        for _ in range(num_frames):
            # Notes: precomputing reusing packets does not work!
            # I.e., you cannot do `packets = encode(...)`
            # and reuse it, as it seems that `mux(...)`
            # consumes the packet.
            # The same issue applies for `av_frame`,
            # reusing it renders weird-looking frames.
            av_frame = av.VideoFrame.from_ndarray(frame, format="rgba")
            _packets_muxed = 0
            for packet in self.video_stream.encode(av_frame):
                self.video_container.mux(packet)
                _packets_muxed += 1
            # Packet-level trace — fires on frame #2 if the encoder
            # is silently dropping packets (fps mismatch / pix_fmt
            # mismatch / codec init half-completed).
            if _packets_muxed == 0:
                print(f"[manim-debug] ! encode() returned 0 packets "
                      f"(codec={self.video_stream.codec.name if self.video_stream else '?'}, "
                      f"pix_fmt={getattr(self.video_stream, 'pix_fmt', '?')}, "
                      f"size={frame.shape[1]}x{frame.shape[0]})",
                      flush=True)

    def join_all_encode_jobs(self) -> None:
        """Nothing to wait for: each clip is finished when it is closed
        (0.22 encodes several at once, and joins them here)."""

    def abort_encode_jobs(self, reraise_encoder_failures: bool = False) -> None:
        """Discard the clip being written, stopping its writer thread.

        A render that fails (or is stopped) mid-animation lands here through
        the scene's manager. When ``reraise_encoder_failures`` is true, the
        encoder's own failure is raised; otherwise it is logged so the
        render's exception stays the one reported.
        """
        clip = self._clip_encoding
        if clip is None:
            return
        thread = self.writer_thread
        clip.closing.set()
        # Empty the queue, so a renderer blocked in put and the thread both
        # move on, then ask the thread to stop.
        while True:
            try:
                clip.queue.get_nowait()
            except Empty:
                break
        with suppress(Full):
            clip.queue.put_nowait((-1, None))
        if thread is not None:
            # It finishes the frame it is encoding.
            thread.join(timeout=10)
        error = clip.error
        if thread is not None and thread.is_alive():
            # A stuck encoder: the thread is still inside it, and muxes into
            # this clip's stream and container when it comes back. Dropping
            # them under it was manim 0.20's `None.mux`; the clip is left as
            # it is (the thread is a daemon), and its file with it.
            logger.error(
                "The video encoder of aborted animation %s is still running; "
                "its partial movie file is left in place",
                self.animation_index,
            )
            if reraise_encoder_failures and error is not None:
                raise error
            return
        container = self.video_container
        path = self.partial_movie_file_path
        with suppress(Exception):
            container.close()
        self.video_stream = None
        self.video_container = None
        self.queue = None
        self.writer_thread = None
        self._clip_encoding = None
        if path is not None:
            with suppress(OSError):
                Path(path).unlink(missing_ok=True)
        if error is not None:
            logger.error(
                "Encoder for aborted animation %s had also failed",
                self.animation_index,
                exc_info=error,
            )
            if reraise_encoder_failures:
                raise error
        else:
            logger.info(
                "Discarded partial movie file of aborted animation %(index)s",
                {"index": self.animation_index},
            )

    def close_partial_movie_stream(self) -> None:
        """Wait for the clip's writer thread to encode everything queued,
        then flush the encoder and close the clip's container."""
        clip = self._clip_encoding
        if clip is None:
            raise RuntimeError(
                "close_partial_movie_stream() called without an open partial "
                "movie stream.",
            )
        queue = clip.queue
        try:
            qsize_before = queue.qsize()
        except Exception:
            qsize_before = -1
        print(f"[manim-debug] close_partial_movie_stream: queue depth={qsize_before}, "
              f"joining writer thread…", flush=True)
        clip.closing.set()
        try:
            queue.put_nowait((-1, None))
        except Full:
            # The writer is behind. It stops by itself once the queue is
            # empty (clip.closing), so there is no need to wait for room.
            pass
        # Nothing below may run while the writer thread does: it is still
        # muxing into this clip's container. This waits for as long as frames
        # keep coming out, and raises if none have for the stall window.
        self._wait_for_writer(self.writer_thread, clip, queue)
        if clip.error is not None:
            error = clip.error
            self.abort_encode_jobs()
            raise RuntimeError(
                f"the video encoder stopped: {type(error).__name__}: {error}"
            ) from error

        # Flush any encoder-buffered frames (B-frames, lookahead, etc.).
        try:
            flushed = 0
            for packet in self.video_stream.encode():
                self.video_container.mux(packet)
                flushed += 1
            print(f"[manim-debug]   flushed {flushed} trailing packet(s)", flush=True)
        except Exception as error:
            print(f"[manim-debug] ! flush failed: {type(error).__name__}: {error}",
                  flush=True)

        try:
            self.video_container.close()
            print(f"[manim-debug]   container closed, file={self.partial_movie_file_path}",
                  flush=True)
        except Exception as error:
            print(f"[manim-debug] ! container close failed: {type(error).__name__}: {error}",
                  flush=True)

        # Safe now: the writer thread has exited (_wait_for_writer).
        self.video_stream = None
        self.video_container = None
        self.queue = None
        self.writer_thread = None
        self._clip_encoding = None
        if _on_ios():
            self._release_memory_after_clip()
        logger.info(
            f"Animation {self.animation_index} : Partial movie file written in %(path)s",
            {"path": f"'{self.partial_movie_file_path}'"},
        )

    @staticmethod
    def _release_memory_after_clip() -> None:
        """iOS: free what a clip leaves behind before the next one's peak.

        PyAV's stream and container hold native buffers (hundreds of MB on
        iOS) that are freed only with their last Python reference; the SVG
        and number caches never evict (ManimCommunity/manim#4327); and
        libmalloc keeps freed pages dirty until asked. Long scenes crossed
        the jetsam limit around animation 18-25 without this.
        """
        try:
            from manim.mobject.svg.svg_mobject import SVG_HASH_TO_MOB_MAP

            SVG_HASH_TO_MOB_MAP.clear()
        except Exception:
            pass
        try:
            from manim.mobject.text import numbers as _nums

            _nums.string_to_mob_map.clear()
        except Exception:
            pass
        import gc as _gc

        _gc.collect()
        # A second pass reaps cycles that involve both Python and
        # Cython-wrapped objects, which the first can leave behind.
        _gc.collect()
        try:
            import ctypes as _ct
            import ctypes.util as _ctu

            _libc = _ct.CDLL(_ctu.find_library("c") or "libc.dylib")
            if hasattr(_libc, "malloc_zone_pressure_relief"):
                _libc.malloc_zone_pressure_relief.argtypes = [_ct.c_void_p, _ct.c_size_t]
                _libc.malloc_zone_pressure_relief.restype = _ct.c_size_t
                _libc.malloc_zone_pressure_relief(None, 0)
        except Exception:
            pass

    def _wait_for_writer(self, thread: Thread | None, clip: _ClipEncoding | None,
                         queue: Queue | None) -> None:
        """Wait until this clip's writer thread has encoded its queue and exited.

        Waits in short slices for as long as the thread keeps encoding frames —
        there is no deadline, because a slow encoder is not a broken one, and an
        8K frame through VideoToolbox plus the RGBA conversion takes long
        enough that 32 queued frames are well over a minute on an iPad. Only if
        no frame has come out for the stall window
        (``settings.encoder_stall_window``) does it give up, by raising, so the
        container is never closed under a thread still writing into it.

        Short slices also let a Stop reach the render thread within a second:
        a KeyboardInterrupt raised into it lands between two of them.
        """
        if thread is None or not thread.is_alive():
            return
        from manim.utils.ios_encoder import settings as _st

        spec = self.video_encoder
        width, height = (spec.width, spec.height) if spec is not None else (0, 0)
        limit, reason = _st.refresh().encoder_stall_window(width, height)
        slice_s = 1.0
        waited = 0.0
        stalled = 0.0
        next_note = 60.0
        seen = clip.encoded if clip is not None else 0
        seen_at_note = seen

        def left() -> int:
            if clip is not None:
                return clip.left
            try:
                return queue.qsize() if queue is not None else -1
            except Exception:
                return -1

        while thread.is_alive():
            started = time.monotonic()
            thread.join(timeout=slice_s)
            if not thread.is_alive():
                break
            # A slice that took far longer than it asked for means the process
            # itself was stopped — iOS suspends an app in the background, and
            # the encoder with it. That is a pause, not a stall.
            ran = min(time.monotonic() - started, slice_s * 3)
            waited += ran
            if clip is not None and clip.encoded != seen:
                seen = clip.encoded
                stalled = 0.0
            else:
                stalled += ran
            if waited >= next_note:
                if clip is None or seen != seen_at_note:
                    print(f"[manim-debug] writer still encoding ({left()} frames left), "
                          f"waiting… ({int(waited)} s so far)", flush=True)
                else:
                    print(f"[manim-debug] writer has encoded nothing for {int(stalled)} s "
                          f"({left()} frames left; gives up at {limit} s), waiting…",
                          flush=True)
                seen_at_note = seen
                next_note += 60.0
            if limit and stalled >= limit:
                print(f"[manim-debug] ! writer thread made no progress for "
                      f"{int(stalled)} s — render is stuck", flush=True)
                raise RuntimeError(
                    f"the video encoder made no progress for {int(stalled)} s at "
                    f"{width}x{height} ({left()} frame(s) still queued; the limit "
                    f"is {limit} s, {reason} — settings.encoder_stall_seconds or "
                    f"OFFLINAI_MANIM_ENCODER_STALL_S changes it)")

    def is_already_cached(self, hash_invocation: str) -> bool:
        """Will check if a file named with `hash_invocation` exists.

        Parameters
        ----------
        hash_invocation
            The hash corresponding to an invocation to either `scene.play` or `scene.wait`.

        Returns
        -------
        :class:`bool`
            Whether the file exists.
        """
        if not self.output_spec.is_video:
            return False
        return self.output_plan.segment_path(hash_invocation).exists()

    @staticmethod
    def _concat_manifest_bytes(input_files: list[str]) -> bytes:
        """Return a complete FFmpeg concat manifest for ``input_files``."""
        manifest_text = (
            "# This file records the segment order used by Manim.\n"
            + "".join(
                f"file 'file:{Path(file_path).as_posix()}'\n"
                for file_path in input_files
            )
        )
        return manifest_text.encode("utf-8")
    def _write_concat_manifest(self, input_files: list[str]) -> None:
        """Atomically persist the complete scene segment order for diagnostics."""
        manifest_path = self.output_plan.concat_manifest
        assert manifest_path is not None
        manifest_path.parent.mkdir(parents=True, exist_ok=True)
        temporary_path: Path | None = None
        try:
            with NamedTemporaryFile(
                mode="wb",
                dir=manifest_path.parent,
                prefix=f".{manifest_path.name}.",
                suffix=".tmp",
                delete=False,
            ) as temporary_file:
                temporary_path = Path(temporary_file.name)
                temporary_file.write(self._concat_manifest_bytes(input_files))
            temporary_path.replace(manifest_path)
        except BaseException:
            if temporary_path is not None:
                with suppress(OSError):
                    temporary_path.unlink(missing_ok=True)
            raise
    def combine_files(
        self,
        input_files: list[str],
        output_file: Path,
        create_gif: bool = False,
        includes_sound: bool = False,
    ) -> None:
        output_file.parent.mkdir(parents=True, exist_ok=True)
        logger.debug(
            f"Partial movie files to combine ({len(input_files)} files): %(p)s",
            {"p": input_files[:5]},
        )
        manifest = BytesIO(self._concat_manifest_bytes(input_files))

        av_options = {
            "safe": "0",  # needed to read files
        }

        if not includes_sound:
            av_options["an"] = "1"

        partial_movies_input = av.open(
            manifest,
            options=av_options,
            format="concat",
        )
        partial_movies_stream = partial_movies_input.streams.video[0]
        output_container = av.open(str(output_file), mode="w")
        output_container.metadata["comment"] = (
            f"Rendered with Manim Community v{__version__}"
        )
        if create_gif:
            """The following solution was largely inspired from this comment
            https://github.com/imageio/imageio/issues/995#issuecomment-1580533018,
            and the following code
            https://github.com/imageio/imageio/blob/65d79140018bb7c64c0692ea72cb4093e8d632a0/imageio/plugins/pyav.py#L927-L996.
            """
            output_stream = output_container.add_stream(
                codec_name="gif",
            )
            output_stream.pix_fmt = "rgb8"
            if self.output_spec.transparent:
                output_stream.pix_fmt = "pal8"
            encoder = self.video_encoder
            assert encoder is not None
            output_stream.width = encoder.width
            output_stream.height = encoder.height
            output_stream.rate = encoder.frame_rate
            graph = av.filter.Graph()
            input_buffer = graph.add_buffer(template=partial_movies_stream)
            split = graph.add("split")
            palettegen = graph.add("palettegen", "stats_mode=diff")
            paletteuse = graph.add(
                "paletteuse", "dither=bayer:bayer_scale=5:diff_mode=rectangle"
            )
            output_sink = graph.add("buffersink")

            input_buffer.link_to(split)
            split.link_to(palettegen, 0, 0)  # 1st input of split -> input of palettegen
            split.link_to(paletteuse, 1, 0)  # 2nd output of split -> 1st input
            palettegen.link_to(paletteuse, 0, 1)  # output of palettegen -> 2nd input
            paletteuse.link_to(output_sink)

            graph.configure()

            for frame in partial_movies_input.decode(video=0):
                graph.push(frame)

            graph.push(None)  # EOF: https://github.com/PyAV-Org/PyAV/issues/886.

            frames_written = 0
            while True:
                try:
                    frame = graph.pull()
                    if output_stream.codec_context.time_base is not None:
                        frame.time_base = output_stream.codec_context.time_base
                    frame.pts = frames_written
                    frames_written += 1
                    output_container.mux(output_stream.encode(frame))
                except av.error.EOFError:
                    break

            for packet in output_stream.encode():
                output_container.mux(packet)

        else:
            output_stream = output_container.add_stream_from_template(
                template=partial_movies_stream,
            )
            # A template carries the codec but not its mp4 tag, so an HEVC
            # render came back out of the concatenation as `hev1` even though
            # every partial was written as `hvc1`; AVFoundation reports a
            # `hev1` file as neither playable nor decodable. The name here is
            # the *encoder* ffmpeg would use for the copy, which for HEVC is
            # `libx265`, not `hevc`: matching the family is what makes it fire.
            out_codec = (getattr(output_stream.codec_context, "name", "") or "").lower()
            if "hevc" in out_codec or "265" in out_codec:
                try:
                    output_stream.codec_tag = "hvc1"
                except Exception as tag_error:
                    print(f"[manim-debug] combine: hvc1 tag rejected: "
                          f"{type(tag_error).__name__}: {tag_error}", flush=True)
            if (
                self.output_spec.transparent
                and self.output_spec.segment_extension == ".webm"
            ):
                output_stream.pix_fmt = "yuva420p"
            for packet in partial_movies_input.demux(partial_movies_stream):
                # We need to skip the "flushing" packets that `demux` generates.
                if packet.dts is None:
                    continue

                packet.dts = None  # This seems to be needed, as dts from consecutive
                # files may not be monotically increasing, so we let libav compute it.

                # We need to assign the packet to the new stream.
                packet.stream = output_stream
                output_container.mux(packet)

        partial_movies_input.close()
        output_container.close()
        manifest.close()
    def combine_to_movie(self) -> None:
        """Used internally by Manim to combine the separate
        partial movie files that make up a Scene into a single
        video file for that Scene.
        """
        partial_movie_files = [el for el in self.partial_movie_files if el is not None]
        # NOTE: Here we should do a check and raise an exception if partial
        # movie file is empty.  We can't, as a lot of stuff (in particular, in
        # tests) use scene initialization, and this error would be raised as
        # it's just an empty scene initialized.

        # determine output path
        movie_file_path = self.movie_file_path
        if self.output_spec.is_gif:
            movie_file_path = self.gif_file_path

        if len(partial_movie_files) == 0:  # Prevent calling concat on empty list
            logger.info("No animations are contained in this scene.")
            return

        logger.info("Combining to Movie file.")
        self._fill_holds_before_reencoding(partial_movie_files)
        self._write_concat_manifest(partial_movie_files)
        self.combine_files(
            partial_movie_files,
            movie_file_path,
            self.output_spec.is_gif,
            self.includes_sound,
        )

        # handle sound
        if self.includes_sound and not self.output_spec.is_gif:
            sound_file_path = movie_file_path.with_suffix(".wav")
            # Makes sure sound file length will match video file
            self.add_audio_segment(AudioSegment.silent(0))
            self.audio_segment.export(
                sound_file_path,
                format="wav",
                bitrate="312k",
            )
            # Audio added to a VP9 encoded (webm) video file needs
            # to be encoded as vorbis or opus. Directly exporting
            # self.audio_segment with such a codec works in principle,
            # but tries to call ffmpeg via its CLI -- which we want
            # to avoid. This is why we need to do the conversion
            # manually.
            if self.output_spec.segment_extension == ".webm":
                ogg_sound_file_path = sound_file_path.with_suffix(".ogg")
                convert_audio(sound_file_path, ogg_sound_file_path, _webm_audio_codec())
                sound_file_path = ogg_sound_file_path
            elif self.output_spec.segment_extension == ".mp4":
                # Similarly, pyav may reject wav audio in an .mp4 file;
                # convert to AAC.
                aac_sound_file_path = sound_file_path.with_suffix(".aac")
                convert_audio(sound_file_path, aac_sound_file_path, "aac")
                sound_file_path = aac_sound_file_path

            temp_file_path = movie_file_path.with_name(
                f"{movie_file_path.stem}_temp{movie_file_path.suffix}"
            )
            av_options = {
                "shortest": "1",
                "metadata": f"comment=Rendered with Manim Community v{__version__}",
            }

            with (
                av.open(movie_file_path) as video_input,
                av.open(sound_file_path) as audio_input,
            ):
                video_stream = video_input.streams.video[0]
                audio_stream = audio_input.streams.audio[0]
                output_container = av.open(
                    str(temp_file_path), mode="w", options=av_options
                )
                output_video_stream = output_container.add_stream_from_template(
                    template=video_stream
                )
                output_audio_stream = output_container.add_stream_from_template(
                    template=audio_stream
                )

                for packet in video_input.demux(video_stream):
                    # We need to skip the "flushing" packets that `demux` generates.
                    if packet.dts is None:
                        continue

                    # We need to assign the packet to the new stream.
                    packet.stream = output_video_stream
                    output_container.mux(packet)

                for packet in audio_input.demux(audio_stream):
                    # We need to skip the "flushing" packets that `demux` generates.
                    if packet.dts is None:
                        continue

                    # We need to assign the packet to the new stream.
                    packet.stream = output_audio_stream
                    output_container.mux(packet)

                output_container.close()

            shutil.move(str(temp_file_path), str(movie_file_path))
            sound_file_path.unlink()

        self.print_file_ready_message(str(movie_file_path))
        if self.output_spec.is_video:
            for file_path in partial_movie_files:
                # We have to modify the accessed time so if we have to clean the cache we remove the one used the longest.
                modify_atime(file_path)
    def combine_to_section_videos(self) -> None:
        """Concatenate partial movie files for each section."""
        self.finish_last_section()
        sections_index: list[dict[str, Any]] = []
        for section in self.sections:
            # only if section does want to be saved
            if section.video is not None:
                logger.info(f"Combining partial files for section '{section.name}'")
                section_path = self.sections_output_dir / section.video
                self._fill_holds_before_reencoding(section.get_clean_partial_movie_files())
                self.combine_files(
                    section.get_clean_partial_movie_files(),
                    section_path,
                )
                sections_index.append(section.get_dict(self.sections_output_dir))
        section_index = self.output_plan.section_index
        assert section_index is not None
        section_index.parent.mkdir(parents=True, exist_ok=True)
        with section_index.open("w") as file:
            json.dump(sections_index, file, indent=4)
    def write_subcaption_file(self) -> None:
        """Writes the subcaption file next to the primary video artifact."""
        if not self.output_spec.is_video:
            return
        subcaption_file = self.output_plan.subcaption_file
        assert subcaption_file is not None
        subcaption_file.parent.mkdir(parents=True, exist_ok=True)
        subcaption_file.write_text(srt.compose(self.subcaptions), encoding="utf-8")
        logger.info(f"Subcaption file has been written as {subcaption_file}")
    def print_file_ready_message(self, file_path: StrPath) -> None:
        """Record and report a completed primary artifact."""
        self.final_file_path = Path(file_path)
        logger.info("\nFile ready at %(file_path)s\n", {"file_path": f"'{file_path}'"})
